#ifndef CSM_SCREEN_H
#define CSM_SCREEN_H

#include <stddef.h>

/*
 * Colours: 0-255 the terminal's palette (the first 16 its own named
 * colours), COLOR_DEFAULT the screen's text or background, COLOR_RGB a
 * 24-bit one, sent as the nearest of the 256 when the terminal has no
 * full colour.
 */
enum {
	COLOR_RED = 1,
	COLOR_YELLOW = 3,
	COLOR_GRAY = 8,
	COLOR_BRIGHT_RED = 9,
	COLOR_BRIGHT_YELLOW = 11,
	COLOR_DEFAULT = 256
};

#define COLOR_RGB(v) (0x1000000UL | (unsigned long)(v))

#define STYLE_BOLD 1
#define STYLE_DIM 2
#define STYLE_UNDERLINE 4
#define STYLE_REVERSE 8

/* fg and bg COLOR_DEFAULT: the screen's text and background. */
struct attr {
	unsigned long fg, bg;
	unsigned char style;
};

/* One character with its combining marks; "" is the right half of a wide one. */
struct cell {
	char text[16];
	struct attr attr;
};

/*
 * A frame buffer: the program draws into back, flush sends the cells that
 * differ from front (what the terminal shows) and makes them equal.
 */
struct screen {
	size_t cols, rows;
	struct cell *back, *front;
	int valid;		/* front matches the terminal */
	int color;		/* 0: styles only (NO_COLOR) */
	int truecolor;		/* the terminal takes 24-bit colours */
	unsigned long fg, bg;	/* what COLOR_DEFAULT means; a theme sets them */
	int cursor_on;
	size_t cursor_x, cursor_y;
	int cursor_shown;	/* on the terminal; -1 when not known */
	size_t shown_x, shown_y;	/* where the terminal has the cursor */
};

void screen_init(struct screen *s, size_t cols, size_t rows, int color);
void screen_resize(struct screen *s, size_t cols, size_t rows);
void screen_free(struct screen *s);
void screen_invalidate(struct screen *s);
void screen_colors(struct screen *s, unsigned long fg, unsigned long bg);
void screen_clear(struct screen *s);
size_t screen_text(struct screen *s, size_t x, size_t y, size_t width,
    const char *text, struct attr attr, int right);
char *screen_line(const struct screen *s, size_t y);
int screen_nearest(unsigned long rgb);
char *screen_flush(struct screen *s, size_t *len);

#endif
